- (void)showAttachments{if(!self.attachments.count)return;UIAlertController *a=[UIAlertController alertControllerWithTitle:@"待发送附件" message:@"文件保留参考副本；文件夹只保留目录授权，AI 按需读取。" preferredStyle:UIAlertControllerStyleActionSheet];for(NSDictionary *item in self.attachments)[a addAction:[UIAlertAction actionWithTitle:[NSString stringWithFormat:@"%@ · %@ B",item[@"path"],item[@"bytes"]] style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){UIViewController *v=TFAIAttachmentPreview(item);v.title=item[@"path"];v.navigationItem.rightBarButtonItem=[[UIBarButtonItem alloc]initWithPrimaryAction:[UIAction actionWithTitle:@"移除" image:[UIImage systemImageNamed:@"trash"] identifier:nil handler:^(UIAction *action){[self.attachments removeObject:item];[self updateManifest];[self persist];[v.navigationController popViewControllerAnimated:YES];}]];[self.navigationController pushViewController:v animated:YES];}]];[a addAction:[UIAlertAction actionWithTitle:@"移除全部附件" style:UIAlertActionStyleDestructive handler:^(UIAlertAction *x){[self.attachments removeAllObjects];[self updateManifest];[self persist];}]];[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];a.popoverPresentationController.sourceView=self.manifest;[self presentViewController:a animated:YES completion:nil];}
- (void)attachMenu{if(self.running){AIAlert(self,@"任务进行中",@"请先停止任务，再准备附件。");return;}if(self.presentedViewController)return;[self hideKeyboard];if(!self.contextProvider){[self presentAttachmentMenu:@{}];return;}__weak typeof(self) weak=self;self.contextProvider(@"availability",^(NSDictionary *result,NSError *error){dispatch_async(dispatch_get_main_queue(),^{TFAIChat *s=weak;if(!s||s.running||s.presentedViewController)return;[s presentAttachmentMenu:error?@{}:result?:@{}];});});}
- (void)presentAttachmentMenu:(NSDictionary *)contexts{__weak typeof(self) weak=self;UIViewController *menu=TFAIAttachmentMenu(contexts,^(NSString *key){TFAIChat *s=weak;if(!s)return;if([key isEqual:@"photo"]){PHPickerConfiguration *c=[[PHPickerConfiguration alloc]init];c.filter=PHPickerFilter.imagesFilter;c.selectionLimit=3;PHPickerViewController *p=[[PHPickerViewController alloc]initWithConfiguration:c];p.delegate=s;[s presentViewController:p animated:YES completion:nil];}else if([key isEqual:@"camera"]){if(![UIImagePickerController isSourceTypeAvailable:UIImagePickerControllerSourceTypeCamera]){AIAlert(s,@"当前设备没有可用相机",@"请使用照片或文件添加图片。");return;}UIImagePickerController *p=[UIImagePickerController new];p.sourceType=UIImagePickerControllerSourceTypeCamera;p.delegate=s;[s presentViewController:p animated:YES completion:nil];}else if([key isEqual:@"file"]){UIDocumentPickerViewController *p=[[UIDocumentPickerViewController alloc]initForOpeningContentTypes:@[UTTypeImage,UTTypePlainText,UTTypeJSON,UTTypeData] asCopy:YES];p.allowsMultipleSelection=YES;p.delegate=s;[s presentViewController:p animated:YES completion:nil];}else if([key isEqual:@"classdump"]){UIDocumentPickerViewController *picker=[[UIDocumentPickerViewController alloc]initForOpeningContentTypes:@[UTTypeData,UTTypeArchive] asCopy:YES];picker.delegate=s;picker.allowsMultipleSelection=NO;[s presentViewController:picker animated:YES completion:nil];}else if([key isEqual:@"project"])[s chooseFiles];else if(s.contextProvider)s.contextProvider(key,^(NSDictionary *result,NSError *error){if(error)AIAlert(s,@"附加失败",error.localizedDescription);else if([result[@"text"] length]&&(!result[@"available"]||[result[@"available"] boolValue])){[s addContextText:result[@"text"] title:result[@"title"]];[s persist];}});});UINavigationController *nav=[[TMCNavigationController alloc]initWithRootViewController:menu];nav.modalPresentationStyle=UIModalPresentationPageSheet;nav.sheetPresentationController.detents=@[UISheetPresentationControllerDetent.mediumDetent,UISheetPresentationControllerDetent.largeDetent];nav.sheetPresentationController.prefersGrabberVisible=YES;[self presentViewController:nav animated:YES completion:nil];}
- (void)imagePickerControllerDidCancel:(UIImagePickerController *)picker{[picker dismissViewControllerAnimated:YES completion:nil];}
- (void)imagePickerController:(UIImagePickerController *)picker didFinishPickingMediaWithInfo:(NSDictionary<UIImagePickerControllerInfoKey,id> *)info{UIImage *image=info[UIImagePickerControllerOriginalImage];[picker dismissViewControllerAnimated:YES completion:nil];if(image)[self prepareImage:UIImageJPEGRepresentation(image,.85) name:@"相机照片.jpg"];}

- (void)chooseFiles{UIViewController *v=TFAIAttachmentBrowser(self.standalone?nil:self.root,TFAIInternalProjects(),^(NSArray *entries){[self.attachments addObjectsFromArray:entries];[self updateManifest];[self persist];});UINavigationController *nav=[[TMCNavigationController alloc]initWithRootViewController:v];nav.modalPresentationStyle=UIModalPresentationPageSheet;nav.sheetPresentationController.detents=@[UISheetPresentationControllerDetent.largeDetent];[self presentViewController:nav animated:YES completion:nil];}
- (void)addContextText:(NSString *)text title:(NSString *)title {
 if(!self.attachments)self.attachments=[NSMutableArray new];if(![text isKindOfClass:NSString.class]||!text.length)return;
 // Reuse the same secret/content limits for imported diagnostics and selected code.
 NSString *temp=[NSTemporaryDirectory() stringByAppendingPathComponent:[@"TFAI-context-" stringByAppendingString:NSUUID.UUID.UUIDString]];[NSFileManager.defaultManager createDirectoryAtPath:temp withIntermediateDirectories:YES attributes:nil error:nil];NSString *file=[temp stringByAppendingPathComponent:@"context.txt"];[text writeToFile:file atomically:YES encoding:NSUTF8StringEncoding error:nil];NSError *error=nil;NSArray *checked=[TFAISessions contextForPaths:@[@"context.txt"] root:temp error:&error];[NSFileManager.defaultManager removeItemAtPath:temp error:nil];if(error){if(self.isViewLoaded)AIAlert(self,@"附件未添加",error.localizedDescription);return;}NSMutableDictionary *item=[checked.firstObject mutableCopy];item[@"path"]=title.length?title:@"所选文本";[self.attachments addObject:item];[self updateManifest];
}
- (void)picker:(PHPickerViewController *)picker didFinishPicking:(NSArray<PHPickerResult *> *)results{[picker dismissViewControllerAnimated:YES completion:nil];for(PHPickerResult *result in results)[result.itemProvider loadDataRepresentationForTypeIdentifier:UTTypeImage.identifier completionHandler:^(NSData *data,NSError *error){if(data)[self prepareImage:data name:@"照片"];else dispatch_async(dispatch_get_main_queue(),^{AIAlert(self,@"读取图片失败",error.localizedDescription?:@"请重试");});}];}
- (void)prepareImage:(NSData *)data name:(NSString *)name {
 dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED,0),^{if(data.length>20*1024*1024){dispatch_async(dispatch_get_main_queue(),^{AIAlert(self,@"图片较大",@"请选择小于 20 MB 的图片。");});return;}CGImageSourceRef source=CGImageSourceCreateWithData((__bridge CFDataRef)data,NULL);if(!source)return;CGImageRef thumb=CGImageSourceCreateThumbnailAtIndex(source,0,(__bridge CFDictionaryRef)@{(id)kCGImageSourceCreateThumbnailFromImageAlways:@YES,(id)kCGImageSourceThumbnailMaxPixelSize:@1600,(id)kCGImageSourceCreateThumbnailWithTransform:@YES});CFRelease(source);if(!thumb)return;UIImage *image=[UIImage imageWithCGImage:thumb];CGImageRelease(thumb);NSData *jpeg=UIImageJPEGRepresentation(image,.8);if(jpeg.length>1200*1024)jpeg=UIImageJPEGRepresentation(image,.55);dispatch_async(dispatch_get_main_queue(),^{NSUInteger count=0;for(NSDictionary *a in self.attachments)if([a[@"kind"] isEqual:@"image"])count++;if(count>=3||jpeg.length>1500*1024){AIAlert(self,@"图片附件超限",@"最多 3 张，压缩后每张不超过 1.5 MB。");return;}if(jpeg)[self.attachments addObject:@{@"id":NSUUID.UUID.UUIDString,@"path":name?:@"图片",@"kind":@"image",@"mime":@"image/jpeg",@"bytes":@(jpeg.length),@"data":[jpeg base64EncodedStringWithOptions:0]}];[self updateManifest];[self persist];});});
}
- (void)documentPicker:(UIDocumentPickerViewController *)controller didPickDocumentsAtURLs:(NSArray<NSURL *> *)urls{self.status.text=@"正在准备所选文件或目录授权…";BOOL hasIPA=NO;for(NSURL *url in urls)if([url.pathExtension.lowercaseString isEqual:@"ipa"])hasIPA=YES;if(hasIPA){if(urls.count!=1){AIAlert(self,@"请单独选择 IPA",@"大型 IPA 作为本机工具附件导入，图片和其他文件可另行添加。");return;}self.loading=YES;[self updateSend];dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED,0),^{NSError *error=nil;NSDictionary *entry=TFAIClassDumpStage(urls.firstObject,&error);dispatch_async(dispatch_get_main_queue(),^{self.loading=NO;if(entry){[self.attachments addObject:entry];[self updateManifest];[self persist];self.status.text=@"IPA 已保存本机 · 发送后由 AI 执行导出";}else {AIAlert(self,@"IPA 导入失败",error.localizedDescription);self.status.text=@"未添加 IPA";}[self updateSend];});});return;}TFAIImportAttachmentURLs(urls,^(NSArray *entries,NSError *error){if(error){AIAlert(self,@"附件导入结果",error.localizedDescription);}if(entries.count){[self.attachments addObjectsFromArray:entries];[self updateManifest];[self persist];}BOOL hasDirectory=NO;for(NSDictionary *entry in entries)if(entry[@"directoryGrant"])hasDirectory=YES;self.status.text=hasDirectory?@"目录已授权 · 未复制或上传文件":entries.count?@"已导入本机 · 发送后按需提供给模型":@"未添加附件";});}

@end
UIViewController *TFAIChatController(NSString *root,NSString *projectID,id<TFAIRuntime> runtime,void(^openFile)(NSString *,NSUInteger)){TFAIChat *v=[TFAIChat new];v.root=root;v.projectID=projectID;v.runtime=runtime;v.openFile=openFile;return v;}
void TFAIAddContext(UIViewController *controller,NSString *text,NSString *title){if([controller isKindOfClass:TFAIChat.class])[(TFAIChat *)controller addContextText:text title:title];}
void TFAISetContextProvider(UIViewController *controller,void(^provider)(NSString *,TFAIResult)){if([controller isKindOfClass:TFAIChat.class])[(TFAIChat *)controller setContextProvider:provider];}

void TFAIFlushOpenSession(NSString *project,NSString *identifier){for(TFAIChat *chat in TFAIOpenChats().objectEnumerator.allObjects)if([chat.projectID isEqual:project]&&[chat.session[@"id"] isEqual:identifier])[chat persist];dispatch_sync(AIPersistenceQueue(),^{});}
UIViewController *TFAIConfigureChat(UIViewController *controller,NSDictionary *session,BOOL standalone,void(^associate)(NSDictionary *)){if([controller isKindOfClass:TFAIChat.class]){TFAIChat *chat=(TFAIChat *)controller;NSString *key=TFAIChatKey(chat.root,chat.projectID,session[@"id"]);TFAIChat *active=TFAIActiveChats()[key]?:[TFAIOpenChats() objectForKey:key];if(active){if(!([active.projectID isEqual:@"general"]&&active.projectOwner))active.openFile=chat.openFile;active.contextProvider=chat.contextProvider;active.associate=associate;for(NSDictionary *entry in session[@"pendingAttachments"])if(![active.attachments containsObject:entry])[active.attachments addObject:entry];[active updateManifest];[active persist];return active;}chat.configuredSession=session;chat.standalone=standalone;chat.associate=associate;}return controller;}

void TFAISetProjectContext(UIViewController *controller,id owner,void (^bridge)(NSString *,NSDictionary *,TFAIResult)){if([controller isKindOfClass:TFAIChat.class]){TFAIChat *chat=(TFAIChat *)controller;if([chat.projectID isEqual:@"general"]&&chat.projectOwner)return;chat.projectOwner=owner;TFAIRebindRuntime(chat.runtime,bridge);}}

void TFAISetSessionOpener(UIViewController *controller,void(^open)(NSDictionary *)){if([controller isKindOfClass:TFAIChat.class])[(TFAIChat *)controller setSessionOpener:open];}
